import React from 'react';
import type { FC } from 'react';
import type { PlatformLinkItem } from '@wix/cli-plugin-core';
import { Box, Text } from '@wix/cli-ui-kit';
import { PlatformLink } from './PlatformLink.js';
import { LinkClickTip } from './LinkClickTip.js';

interface PlatformLinksSectionProps {
  // Links in render order. Nothing is rendered when a plugin hid all of them.
  links: readonly PlatformLinkItem[];
}

export const PlatformLinksSection: FC<PlatformLinksSectionProps> = ({
  links,
}) => {
  if (links.length === 0) {
    return null;
  }

  return (
    <Box marginY={1} flexDirection="column" gap={1}>
      <Text>Open the preview on:</Text>
      <Box paddingLeft={2} flexDirection="column">
        {links.map(({ platform, url, label }) => (
          <PlatformLink key={platform} url={url} label={label} />
        ))}
      </Box>
      <LinkClickTip />
    </Box>
  );
};
