import { useCallback } from 'react';
import type { DeploymentTopologyEnvironmentType } from '@wix/cli-astro-definitions';
import type { PlatformLinkItem, PlatformLinkType } from '@wix/cli-plugin-core';
import { useProjectModel } from '../model.js';
import {
  getPlatformLinkCommand,
  resolveAppLinks,
  resolveSiteLinks,
} from '../platform-links/resolve.js';
import { writeDeploymentTopologyEnvironment } from '../files/topology.js';

// A link hidden by a plugin is omitted from the topology entry as well.
function toTopologyLink(
  links: readonly PlatformLinkItem[],
  platform: PlatformLinkType
) {
  const link = links.find((link) => link.platform === platform);
  if (link === undefined) {
    return;
  }
  return { main: link.url };
}

interface UpdateDeploymentTopologyForSiteProps {
  siteUrl: string;
  versionOverrideId: string;
  environment: DeploymentTopologyEnvironmentType;
}

export function useUpdateDeploymentTopologyForSite(siteId: string) {
  const { model } = useProjectModel();

  return useCallback(
    async ({
      environment,
      siteUrl,
      versionOverrideId,
    }: UpdateDeploymentTopologyForSiteProps) => {
      const links = resolveSiteLinks(model, {
        cmd: getPlatformLinkCommand(environment),
        siteId,
        overrideId: versionOverrideId,
        siteUrl,
      });

      await writeDeploymentTopologyEnvironment(
        model.projectFolder,
        environment,
        {
          id: versionOverrideId,
          site: toTopologyLink(links, 'site'),
          dashboard: toTopologyLink(links, 'dashboard'),
        }
      );
    },
    [model, siteId]
  );
}

interface UpdateDeploymentTopologyForAppProps {
  versionOverrideId: string;
  environment: DeploymentTopologyEnvironmentType;
}

export function useUpdateDeploymentTopologyForApp(siteId?: string) {
  const { model } = useProjectModel();

  return useCallback(
    async ({
      environment,
      versionOverrideId,
    }: UpdateDeploymentTopologyForAppProps) => {
      const links = resolveAppLinks(model, {
        cmd: getPlatformLinkCommand(environment),
        siteId,
        overrideId: versionOverrideId,
      });

      await writeDeploymentTopologyEnvironment(
        model.projectFolder,
        environment,
        {
          id: versionOverrideId,
          site: toTopologyLink(links, 'site'),
          editor: toTopologyLink(links, 'editor'),
          dashboard: toTopologyLink(links, 'dashboard'),
        }
      );
    },
    [model, siteId]
  );
}
