import { z } from 'zod';
import type { Env, WixAstroConfig } from '@wix/cli-astro-definitions';

const parentSiteIdSchema = z.string().uuid();

// The runtime status `wix env pull` writes to .env.local
// (ACTIVE / COMPLETED / REVERTED), not the backend migration phase.
const ACTIVE_MIGRATION_STATUS = 'ACTIVE';

// While an editor migration is in flight the project on disk stays the child's,
// but the components override the merchant has to open lives on the parent
// metasite, so a Business Manager link built from the child renders nothing.
// Only the dashboard link follows the parent: the site and editor links point
// at the frontend being built, which is still the child.
export function resolveMigrationDashboardSiteId(
  config: WixAstroConfig,
  env: Env
): string | undefined {
  if (config.projectType !== 'Site') {
    return;
  }

  if (env.EDITOR_MIGRATION_STATUS !== ACTIVE_MIGRATION_STATUS) {
    return;
  }

  const parentSiteId = parentSiteIdSchema.safeParse(
    env.EDITOR_MIGRATION_PARENT_SITE_ID
  );
  return parentSiteId.success ? parentSiteId.data : undefined;
}
