import { useMemo } from 'react';
import type { DeploymentTopologyEnvironmentType } from '@wix/cli-astro-definitions';
import type {
  PlatformLinkCommand,
  PlatformLinkItem,
  PlatformLinkType,
} from '@wix/cli-plugin-core';
import type { ProjectModel } from '../model.js';
import { useProjectModel } from '../model.js';
import { resolveMigrationDashboardSiteId } from '../migration/migration-dashboard-site-id.js';
import {
  DEFAULT_PLATFORM_LABELS,
  createRedirectLink,
  getSiteDashboardUrl,
  getSiteEditorUrl,
} from './defaults.js';

// Each deployment topology environment is written by exactly one command.
const ENVIRONMENT_COMMANDS: Record<
  DeploymentTopologyEnvironmentType,
  PlatformLinkCommand
> = {
  development: 'dev',
  preview: 'preview',
  production: 'release',
};

export function getPlatformLinkCommand(
  environment: DeploymentTopologyEnvironmentType
): PlatformLinkCommand {
  return ENVIRONMENT_COMMANDS[environment];
}

function defaultLink(
  platform: PlatformLinkType,
  url: string
): PlatformLinkItem {
  return { platform, label: DEFAULT_PLATFORM_LABELS[platform], url };
}

interface ResolveInput {
  cmd: PlatformLinkCommand;
  overrideId: string;
  siteId?: string;
}

// Resolves the default links through the project plugins. Plugins'
// `platformLinks` is a pure function, so this may be called freely wherever
// links are needed. The returned list is in render order.
function resolvePlatformLinks(
  model: ProjectModel,
  input: ResolveInput,
  links: PlatformLinkItem[]
): PlatformLinkItem[] {
  if (model.pluginsInterface === undefined) {
    return links;
  }

  return model.pluginsInterface.resolvePlatformLinks({
    ...input,
    appId: model.config.appId,
    links,
  });
}

interface SiteLinksInput extends ResolveInput {
  siteId: string;
  siteUrl: string;
}

// Both the terminal output and `.wix/topology.json` are derived from this, so
// they can never disagree.
export function resolveSiteLinks(
  model: ProjectModel,
  { cmd, siteId, overrideId, siteUrl }: SiteLinksInput
): PlatformLinkItem[] {
  const dashboardSiteId =
    resolveMigrationDashboardSiteId(model.config, model.env) ?? siteId;

  return resolvePlatformLinks(model, { cmd, overrideId, siteId }, [
    defaultLink('site', siteUrl),
    defaultLink('dashboard', getSiteDashboardUrl(dashboardSiteId, overrideId)),
    defaultLink('editor', getSiteEditorUrl(siteId)),
  ]);
}

type AppLinksInput = ResolveInput;

export function resolveAppLinks(
  model: ProjectModel,
  { cmd, siteId, overrideId }: AppLinksInput
): PlatformLinkItem[] {
  const redirect = (platform: PlatformLinkType) =>
    createRedirectLink({
      platform,
      appId: model.config.appId,
      versionOverrideId: overrideId,
      siteId,
    });

  return resolvePlatformLinks(model, { cmd, overrideId, siteId }, [
    defaultLink('site', redirect('site')),
    defaultLink('editor', redirect('editor')),
    defaultLink('dashboard', redirect('dashboard')),
  ]);
}

export function useSiteLinks({
  cmd,
  siteId,
  overrideId,
  siteUrl,
}: SiteLinksInput): PlatformLinkItem[] {
  const { model } = useProjectModel();
  return useMemo(
    () => resolveSiteLinks(model, { cmd, siteId, overrideId, siteUrl }),
    [model, cmd, siteId, overrideId, siteUrl]
  );
}

export function useAppLinks({
  cmd,
  siteId,
  overrideId,
}: AppLinksInput): PlatformLinkItem[] {
  const { model } = useProjectModel();
  return useMemo(
    () => resolveAppLinks(model, { cmd, siteId, overrideId }),
    [model, cmd, siteId, overrideId]
  );
}
